"use client"

export default function Component() {
  return (
    <div className="relative w-full h-screen overflow-hidden">
      {/* Spline 3D Embed */}
      <iframe
        src="https://my.spline.design/cubes-A0T7CP5J2qsawolli9BlhInB/"
        className="w-full h-full border-0"
        title="3D Cubes Scene"
      />

      {/* Gradient Shadow Overlay */}
      <div className="absolute inset-0 pointer-events-none">
        {/* Main gradient overlay */}
        <div
          className="absolute inset-0"
          style={{
            background: `
              linear-gradient(
                180deg,
                rgba(0, 188, 212, 0.3) 0%,
                rgba(0, 150, 180, 0.4) 25%,
                rgba(0, 100, 120, 0.6) 50%,
                rgba(0, 50, 70, 0.8) 75%,
                rgba(0, 20, 30, 0.9) 100%
              )
            `,
          }}
        />

        {/* Additional atmospheric depth */}
        <div
          className="absolute inset-0"
          style={{
            background: `
              radial-gradient(
                ellipse at center bottom,
                rgba(0, 0, 0, 0.4) 0%,
                rgba(0, 0, 0, 0.2) 40%,
                transparent 70%
              )
            `,
          }}
        />

        {/* Subtle vignette effect */}
        <div
          className="absolute inset-0"
          style={{
            background: `
              radial-gradient(
                ellipse at center,
                transparent 30%,
                rgba(0, 0, 0, 0.1) 70%,
                rgba(0, 0, 0, 0.3) 100%
              )
            `,
          }}
        />
      </div>
    </div>
  )
}
